import{_ as o,C as s,o as i,c as r,a3 as a,E as n}from"./chunks/framework.uTHcANy5.js";const u=JSON.parse('{"title":"What is Mosaic","description":"","frontmatter":{},"headers":[],"relativePath":"welcome/index.md","filePath":"welcome/index.md"}'),c={name:"welcome/index.md"};function d(l,e,h,m,p,g){const t=s("MosaicViewer");return i(),r("div",null,[e[0]||(e[0]=a('<h1 id="what-is-mosaic" tabindex="-1">What is Mosaic <a class="header-anchor" href="#what-is-mosaic" aria-label="Permalink to &quot;What is Mosaic&quot;">​</a></h1><p>Mosaic is a file format for <strong>incremental collaboration on geometric, structured data</strong>. Many data sources may be combined to form a bigger composed picture, but in the composition they <strong>retain their identity and lineage</strong>.</p><p>It takes lessons from, and addresses shortcomings of, modern data patterns from <em>USD</em>, <em>ECS</em>, <em>JSON</em> and <em>glTF</em>, and combines them into a single flexible data system. Mosaic:</p><ul><li>is unopinionated on your data</li><li>can serialize &amp; validate any data type with JSON Schema component schemas</li><li>allows people to collaborate on that data through file exchange or API</li><li>takes an ECS approach to decoupling data from use cases</li><li>elevates parent-child relationships to allow for geometric assembly reuse</li><li>supports semantic typing through native inheritance</li></ul><h2 id="in-one-paragraph" tabindex="-1">In one paragraph <a class="header-anchor" href="#in-one-paragraph" aria-label="Permalink to &quot;In one paragraph&quot;">​</a></h2><p>A Mosaic file is a list of <strong>sections</strong>, each a layer of edits with its author, time and reason. Each section adds or changes <strong>nodes</strong>, which are ids carrying <strong>components</strong>: typed values described by JSON Schema, such as a name, a transform, a mesh or a property set. A file can <strong>import</strong> other files, and its sections layer over theirs. So a model is never one big snapshot. It is many small, owned pieces, composed when you look at them, each still saying where it came from.</p>',6)),n(t,{example:"helmet",caption:"A scene importing a model — two archives, one placing the other."}),e[1]||(e[1]=a('<p>Read on for <a href="/mosaic/dist/docs/welcome/why">why Mosaic exists</a> and <a href="/mosaic/dist/docs/welcome/who">who it is for</a>, or jump to <a href="/mosaic/dist/docs/standard/file/format">the format, by example</a>.</p><div class="warning custom-block"><p class="custom-block-title">Status</p><p>Mosaic is pre-1.0 and in active development. Expect breaking changes to both the schema and the generated code layout.</p></div><h2 id="the-repository" tabindex="-1">The repository <a class="header-anchor" href="#the-repository" aria-label="Permalink to &quot;The repository&quot;">​</a></h2><p>This repository holds the format&#39;s specification and the tooling used to work with it:</p><ul><li><strong><code>src</code></strong> — the format definition, written in <a href="https://typespec.io" target="_blank" rel="noreferrer">TypeSpec</a>, which emits the canonical JSON Schema.</li><li><strong><code>standard</code></strong> — the emitted JSON Schema, checked in so consumers can use it without running the toolchain.</li><li><strong><code>sdk</code></strong> — runtime libraries (in progress), the <code>mosaic</code> CLI, and <code>sdk/scenarios</code>, where what a user actually does is written in prose and the test beside it is generated from that.</li></ul><p>How these relate, and which of them is the standard, is described in <a href="/mosaic/dist/docs/standard/">The standard and its implementations</a>.</p>',6))])}const _=o(c,[["render",d]]);export{u as __pageData,_ as default};
